# Style definitions
HEADER_FILL = PatternFill(start_color="1F4E78", end_color="1F4E78", fill_type="solid")
HEADER_FONT = Font(name="Tahoma", size=11, bold=True, color="FFFFFF")
DATA_FONT = Font(name="Tahoma", size=10)
BOLD_DATA_FONT = Font(name="Tahoma", size=10, bold=True)
ALIGN_CENTER = Alignment(horizontal="center", vertical="center", wrap_text=True)
ALIGN_RIGHT = Alignment(horizontal="right", vertical="center", wrap_text=True)
THIN_BORDER = Border(
    left=Side(style='thin', color='D9D9D9'),
    right=Side(style='thin', color='D9D9D9'),
    top=Side(style='thin', color='D9D9D9'),
    bottom=Side(style='thin', color='D9D9D9')
)

def style_sheet(ws, headers, rows, col_widths=None):
    ws.views.sheetView[0].rightToLeft = True
    ws.freeze_panes = 'A2'
    
    # Headers
    ws.append(headers)
    for col_num in range(1, len(headers) + 1):
        cell = ws.cell(row=1, column=col_num)
        cell.fill = HEADER_FILL
        cell.font = HEADER_FONT
        cell.alignment = ALIGN_CENTER
        cell.border = THIN_BORDER
        
    # Rows
    for r_idx, row in enumerate(rows, start=2):
        ws.append(row)
        for col_num in range(1, len(row) + 1):
            cell = ws.cell(row=r_idx, column=col_num)
            cell.font = DATA_FONT
            cell.border = THIN_BORDER
            # Align numbers and short codes center, text right
            val = str(cell.value or "")
            if val.startswith("PRJ-") or val.startswith("EV-") or len(val) < 12 or val.isdigit():
                cell.alignment = ALIGN_CENTER
            else:
                cell.alignment = ALIGN_RIGHT
                
    # Auto-adjust column widths
    for col in ws.columns:
        max_len = 0
        col_letter = get_column_letter(col[0].column)
        if col_widths and col_letter in col_widths:
            ws.column_dimensions[col_letter].width = col_widths[col_letter]
            continue
        for cell in col:
            val = str(cell.value or "")
            lines = val.split('\n')
            for l in lines:
                if len(l) > max_len:
                    max_len = len(l)
        calc_width = min(max(max_len * 1.2, 12), 50)
        ws.column_dimensions[col_letter].width = calc_width

