def build_attachment_analysis_status(conn):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "وضعیت پیوست‌ها"
    
    headers = ['پسوند فایل', 'تعداد پیوست‌ها', 'دسته‌بندی محتوایی', 'اهمیت در پروژه']
    cur = conn.cursor()
    cur.execute("""
        SELECT extension, count(*) as cnt 
        FROM attachments 
        WHERE extension != ''
        GROUP BY extension 
        ORDER BY cnt DESC LIMIT 25
    """)
    rows = cur.fetchall()
    
    classified_rows = []
    for ext, cnt in rows:
        e = ext.lower().replace(".", "")
        cat = "سند متنی و اداری"
        imp = "متوسط"
        if e in ['xlsx', 'xls', 'csv']:
            cat = "داده‌ها، مغایرت‌های مالی و کاتالوگ قیمت"
            imp = "بسیار بالا"
        elif e in ['sql', 'ps1', 'bat', 'cmd', 'vbs']:
            cat = "اسکریپت‌های سیستمی و اتوماسیون"
            imp = "بسیار بالا (شواهد فنی)"
        elif e in ['docx', 'doc', 'pdf']:
            cat = "دستورالعمل‌ها، احکام و صورت‌جلسات رسمی"
            imp = "بالا"
        elif e in ['png', 'jpg', 'jpeg', 'bmp', 'emz']:
            cat = "تصاویر لاگ‌ها، خطاها و دیاگرام‌های فنی"
            imp = "متوسط"
        elif e in ['zip', 'rar', '7z']:
            cat = "پکیج‌های نرم‌افزاری و بیلدها"
            imp = "بالا"
        elif e in ['xml', 'json', 'config']:
            cat = "فایل‌های پیکربندی و امضای دیجیتال"
            imp = "بسیار بالا"
        classified_rows.append((f".{e}", cnt, cat, imp))
        
    style_sheet(ws, headers, classified_rows)
    wb.save(os.path.join(BASE_DIR, r"07_Evidence\Attachment_Analysis_Status.xlsx"))
    print("Built Attachment_Analysis_Status.xlsx successfully.")

def build_evidence_index(conn):
    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "نمایه شواهد"
    
    headers = [
        'شناسه سند (Evidence ID)', 'پروژه / فعالیت مرتبط', 'تاریخ و زمان پیام',
        'پوشه منبع', 'موضوع ایمیل (Subject)', 'فرستنده', 'گیرندگان',
        'پیوست‌ها', 'نقش اثبات‌شده مهدی باقری', 'متن کلیدی / شاهد عینی', 'سطح اطمینان'
    ]
    
    cur = conn.cursor()
    # Sample key emails across all phases
    cur.execute("""
        SELECT entry_id, phase, folder_name, sent_time, subject, sender_name, recipients_to, attachment_names, body_snippet, is_sent_by_me
        FROM emails
        WHERE (
            subject LIKE '%AX%' OR subject LIKE '%پوز%' OR subject LIKE '%صندوق%' OR
            subject LIKE '%SQL%' OR subject LIKE '%مودیان%' OR subject LIKE '%مغایرت%' OR
            subject LIKE '%جلسه%' OR subject LIKE '%پروژه%' OR subject LIKE '%انبار%' OR
            subject LIKE '%گزارش%' OR subject LIKE '%سامانه%' OR subject LIKE '%سرور%' OR
            subject LIKE '%Power%' OR subject LIKE '%BI%' OR subject LIKE '%ارتقا%' OR
            subject LIKE '%ثبت چهره%' OR subject LIKE '%مدیسه%' OR subject LIKE '%تامین%'
        )
        ORDER BY sent_time ASC
        LIMIT 250
    """)
    rows = cur.fetchall()
    
    evidence_rows = []
    for idx, r in enumerate(rows, start=1):
        eid, phase, fldr, snt_time, subj, sender, recip, atts, snip, is_sent = r
        role_verified = "مجری مستقیم / تحلیل‌گر / مدیر استقرار" if is_sent else "مسئول پیگیری / ذی‌نفع فنی"
        ev_id = f"EV-{idx:04d}"
        
        # Link project tag based on keywords
        prj_tag = phase
        s_upper = (subj or "").upper()
        if "مودیان" in subj or "TAX" in s_upper:
            prj_tag = "PRJ-06-001 (سامانه مودیان)"
        elif "AX" in s_upper or "داینامیکس" in subj:
            prj_tag = "PRJ-04-001 (Microsoft Dynamics AX)"
        elif "OLTP3" in s_upper or "جداسازی" in subj:
            prj_tag = "PRJ-05-001 (جداسازی دیتابیس OLTP3)"
        elif "BI" in s_upper or "POWER" in s_upper or "OBI" in s_upper:
            prj_tag = "PRJ-06-002 (هوش تجاری BI)"
        elif "تامین" in subj or "SUPPLIER" in s_upper:
            prj_tag = "PRJ-07-001 (درگاه تامین‌کنندگان)"
        elif "ثبت چهره" in subj or "تردد" in subj:
            prj_tag = "PRJ-02-002 (بیومتریک چهره)"
        elif "مغایرت" in subj:
            prj_tag = "مغایرت‌گیری مالی و تراکنش‌ها"
            
        clean_snip = (snip or "").replace("\r", " ").replace("\n", " ")[:200]
        evidence_rows.append((
            ev_id, prj_tag, str(snt_time)[:19], fldr, subj, sender, recip, atts, role_verified, clean_snip, "HIGH"
        ))
        
    style_sheet(ws, headers, evidence_rows)
    wb.save(os.path.join(BASE_DIR, r"07_Evidence\Evidence_Index.xlsx"))
    print("Built Evidence_Index.xlsx successfully.")

